.capability_validation_rows <- list(
  list(id = "contract.python.causal_workflow", node_id = "tests/test_causal.py::test_cross_fitted_ate_recovers_known_effect_and_beats_naive_difference", oracle = "known-effect confounded simulation and analytical AIPW score identity", compared_outputs = "ATE; row score; influence interval", atol = "0.18", rtol = "0.0", reference = "mboostrs causal workflow contract", rationale = "The causal API is evidence-bearing only when nuisance predictions are out of fold and the returned row scores reconstruct an effect known from the simulation. Separate tests cover ATT denominator influence, grouped variance, repeated folds, negative controls, and binary outcomes."),
  list(id = "contract.python.autospec_numeric_levels", node_id = "tests/test_autospec.py::test_three_numeric_levels_fit_group_effects_not_one_code_slope", oracle = "non-monotone three-group coefficient and fitted-mean identity", compared_outputs = "learner type; coefficient dimension; nonlinearity across codes; fitted group means", atol = "0.08", rtol = "0.0", reference = "mboostrs autospec numeric-level contract", rationale = "A numeric code column does not acquire indicator expansion merely because classify_columns calls it categorical. The fitted three-group pattern proves autospec selected a group learner rather than one slope."),
  list(id = "contract.python.autospec_ordered_category", node_id = "tests/test_autospec.py::test_ordered_categorical_warns_that_brandom_drops_the_order", oracle = "declared-order preservation and explicit-loss warning contract", compared_outputs = "warning type and explanation; valid group learner; declared level order; scored alternatives", atol = "0.0", rtol = "0.0", reference = "mboostrs autospec ordered-category contract", rationale = "The current formula path cannot apply ordered numeric learners directly to categorical labels. Keeping a valid group learner is acceptable only when the lost ordering and explicit-score alternatives are visible to the caller."),
  list(id = "contract.python.effects_workflow", node_id = "tests/test_effects.py::test_accumulated_local_effect_recovers_a_linear_fitted_slope", oracle = "analytical linear-effect and weighted-centering identity", compared_outputs = "ALE slope; weighted center; bin support", atol = "0.12", rtol = "0.0", reference = "mboostrs effects workflow contract", rationale = "The effects API retains prediction-scale, population, weights and support. A linear oracle makes the ALE accumulation independently checkable; adjacent tests cover nonidentity-link contrasts, LSS functionals, elasticities, factors, ICE and support refusals."),
  list(id = "contract.python.evaluation_workflow", node_id = "tests/test_evaluation_result.py::test_multinomial_specification_evaluation_retains_full_probability_rows", oracle = "full categorical log-loss and multiclass Brier analytical identities", compared_outputs = "probability rows; categorical log loss; multiclass Brier; class labels", atol = "1e-12", rtol = "1e-12", reference = "mboostrs evaluation workflow contract", rationale = "The shared evaluation result must retain every probability column and stable class identity rather than the upstream partial reported risk. Binary, count, pairing, rolling-fold and fit-budget oracles are covered in the same test module."),
  list(id = "contract.python.interval_score", node_id = "tests/test_diagnostic_input_contract.py::test_weighted_interval_metrics_match_the_proper_score_formula", oracle = "analytical weighted central-interval score", compared_outputs = "coverage; directional miss rates; width; interval score", atol = "1e-14", rtol = "1e-14", reference = "Gneiting-Raftery central interval score identity", rationale = "Width alone rewards empty intervals. The hand calculation verifies that width and alpha-scaled miss penalties are aggregated with the declared evaluation weights while nominal and empirical coverage remain separate."),
  list(id = "contract.python.native_build_identity", node_id = "tests/test_build_info.py::test_build_info_describes_the_loaded_extension", oracle = "compile-time native identity schema", compared_outputs = "package version; source digest; build digest; compiler; target and features; profile; ABI version", atol = "0.0", rtol = "0.0", reference = "mboostrs native build identity schema 1", rationale = "The loaded binary, rather than the current checkout, must identify the native code that produced a fit or benchmark. Package version remains a separate release identifier."),
  list(id = "contract.python.benchmark_native_identity", node_id = "tests/test_build_info.py::test_benchmark_metadata_records_loaded_native_identity", oracle = "loaded-extension build identity equality", compared_outputs = "benchmark native_build record; loaded extension build record", atol = "0.0", rtol = "0.0", reference = "mboostrs benchmark provenance contract", rationale = "A source-tree commit and RUSTFLAGS environment cannot prove which already-built extension was imported. Benchmark artifacts now copy identity from the binary itself."),
  list(id = "contract.python.distribution_evaluation", node_id = "tests/test_distribution_evaluation.py::test_external_gaussian_distribution_scores_are_row_reconstructible", oracle = "analytical Gaussian density, CRPS, PIT, interval-score and exceedance identities", compared_outputs = "density; negative log score; CRPS; PIT; interval score; exceedance probability", atol = "1e-12", rtol = "1e-12", reference = "Gaussian predictive-distribution analytical contract", rationale = "Distributional evaluation must combine every fitted parameter and retain the evaluation-data role. A separate fixed zero-adjusted Gamma test verifies F(y-) to F(y) randomization at an atom while continuous observations remain seed-invariant."),
  list(id = "contract.python.centile_fan", node_id = "tests/test_lss_distribution_profiles.py::test_centile_fan_retains_rows_order_and_split_labels", oracle = "nested conditional-quantile ordering and row-identity contract", compared_outputs = "row identity; covariate ordering; split labels; nested centiles", atol = "0.0", rtol = "0.0", reference = "mboostrs centile-fan contract", rationale = "A centile fan must preserve the fitted row-specific distributions and state that optional split panels facet one model rather than fit separate groups."),
  list(id = "contract.python.density_overlay", node_id = "tests/test_lss_distribution_profiles.py::test_continuous_overlay_averages_row_specific_densities", oracle = "explicit average of row-specific fitted densities", compared_outputs = "fitted mixture density; observed kernel density; density normalization", atol = "2e-06", rtol = "0.0", reference = "mboostrs fitted-distribution overlay contract", rationale = "Evaluating one density at average parameters is not the marginal predictive distribution when scale or shape varies. The test reconstructs the curve from every fitted row and checks both displayed curves integrate to one."),
  list(id = "contract.python.mixed_density_overlay", node_id = "tests/test_lss_distribution_profiles.py::test_mixed_overlay_separates_atom_probability_from_positive_density", oracle = "semicontinuous mass-density decomposition", compared_outputs = "observed atom mass; fitted atom mass; observed positive density integral; fitted positive density integral", atol = "0.004", rtol = "0.0", reference = "zero-adjusted mixture probability identity", rationale = "A probability mass at zero and a density above zero have different units and cannot share one curve. The table and chart keep the atom in a separate panel while both positive-density integrals reconstruct their remaining probability."),
  list(id = "contract.python.deviance_profile", node_id = "tests/test_lss_distribution_profiles.py::test_deviance_profile_reconstructs_weighted_joint_deviance", oracle = "weighted joint-deviance reconstruction", compared_outputs = "bin membership; bin weight; total deviance; mstop-specific profile", atol = "1e-13", rtol = "1e-13", reference = "mboostrs deviance-profile contract", rationale = "An LSS loss is joint across parameters. The profile must localize row contributions without claiming a per-parameter or per-term decomposition, and its bin totals must reconstruct the fitted objective."),
  list(id = "contract.python.bcpelss_workflow", node_id = "tests/test_bct_bcpe.py::test_fitted_family_supports_distributional_workflow[BCPELSS]", oracle = "fitted four-parameter distribution workflow contract", compared_outputs = "response-scale parameters; joint risk; PIT; quantile residuals; centiles; prediction interval", atol = "0.0", rtol = "0.0", reference = "mboostrs BCPELSS workflow contract", rationale = "A family is useful for growth and reference-curve modeling only when its fitted parameters drive the distributional diagnostics without non-finite values or shape loss."),
  list(id = "contract.python.bctlss_workflow", node_id = "tests/test_bct_bcpe.py::test_fitted_family_supports_distributional_workflow[BCTLSS]", oracle = "fitted four-parameter distribution workflow contract", compared_outputs = "response-scale parameters; joint risk; PIT; quantile residuals; centiles; prediction interval", atol = "0.0", rtol = "0.0", reference = "mboostrs BCTLSS workflow contract", rationale = "A family is useful for growth and reference-curve modeling only when its fitted parameters drive the distributional diagnostics without non-finite values or shape loss."),
  list(id = "contract.r.lss_mean", node_id = "mboostrs/tests/test_lss_mean_contract.R", oracle = "analytical mixture and AFT response-mean identities", compared_outputs = "zero-inflated mean; zero-adjusted mean; Pareto moment condition; AFT means; BCCG refusal", atol = "1e-14", rtol = "1e-14", reference = "R analytical LSS mean contract", rationale = "The R frontend now exposes the same response-moment semantics as Python. The contract distinguishes component location from mixture mean and refuses parameters for which the requested moment does not exist."),
  list(id = "contract.r.native_build_identity", node_id = "mboostrs/tests/test_build_info.R", oracle = "compile-time native identity schema", compared_outputs = "package version; source digest; build digest; compiler; target and features; profile; ABI version", atol = "0.0", rtol = "0.0", reference = "mboostrs native build identity schema 1", rationale = ""),
  list(id = "contract.r.centile_fan", node_id = "mboostrs/tests/test_distribution_profiles.R", oracle = "nested conditional-quantile ordering and row-identity contract", compared_outputs = "row identity; split labels; nested centiles", atol = "0.0", rtol = "0.0", reference = "mboostrs R centile-fan contract", rationale = ""),
  list(id = "contract.r.density_overlay", node_id = "mboostrs/tests/test_distribution_profiles.R", oracle = "explicit average of row-specific fitted densities and mixture identity", compared_outputs = "fitted mixture density; density normalization; atom probability", atol = "2e-06", rtol = "0.0", reference = "mboostrs R fitted-distribution overlay contract", rationale = ""),
  list(id = "contract.r.deviance_profile", node_id = "mboostrs/tests/test_distribution_profiles.R", oracle = "joint-deviance reconstruction", compared_outputs = "bin membership; total deviance", atol = "1e-10", rtol = "0.0", reference = "mboostrs R deviance-profile contract", rationale = ""),
  list(id = "contract.python.sklearn_distribution_score", node_id = "tests/test_sklearn_api.py::test_lss_distribution_log_score_matches_fitted_density", oracle = "analytical mean log density from fitted LSS parameter predictions", compared_outputs = "distribution_log_score; family density; location R-squared distinction", atol = "1e-14", rtol = "1e-14", reference = "scikit-learn distribution-score adapter contract", rationale = "LSSRegressor inherits location R-squared from RegressorMixin, which cannot score fitted scale or tails. The dedicated scorer is checked against the family density and documented as requiring held-out data for predictive interpretation."),
  list(id = "contract.python.sklearn_margin_probability", node_id = "tests/test_sklearn_api.py::test_adaexp_tree_exposes_a_margin_not_pseudo_probabilities", oracle = "classification-margin threshold identity", compared_outputs = "decision margin; class prediction; predict_proba availability", atol = "0.0", rtol = "0.0", reference = "scikit-learn classifier response contract", rationale = "AdaExp minimizes exponential classification loss and does not supply calibrated probabilities. The adapter exposes its signed margin and class boundary while hiding predict_proba; Binomial retains probability output."),
  list(id = "contract.python.sklearn_survival_target", node_id = "tests/test_sklearn_api.py::test_survival_accepts_the_structured_target_in_either_field_order", oracle = "event/time structured-target field-name invariance", compared_outputs = "risk score; field-order invariance", atol = "1e-14", rtol = "1e-14", reference = "scikit-survival structured target convention", rationale = "SurvivalBoost locates named event and time fields rather than assuming dtype order. Adjacent tests reject non-finite time, route censored LSS families away from numeric LSSRegressor, and accept full or RHS-only formulas."),
  list(id = "contract.r.artifact_family_params", node_id = "mboostrs/tests/test_artifact_parameter_validation.R", oracle = "typed refusal for an out-of-domain family parameter", compared_outputs = "error message", atol = "0.0", rtol = "0.0", reference = "mboostrs artifact schema 1", rationale = "P0.3 asked for the R and Rust artifact readers to be audited separately, since a Python test is not evidence that they reject the same payload. They did not: a hand-edited artifact with tau = 1.5 on a Quantile family was refused in Python and loaded in R, and the model it produced predicted from a check loss minimised below every observation. Eight out-of-domain values across six families are refused now, and two valid documents still load."),
  list(id = "contract.r.parity_notes", node_id = "mboostrs/tests/test_parity_notes_r.R", oracle = "the mboostrs._parity_notes registry, generated into the R package", compared_outputs = "note names; summary pointer", atol = "0.0", rtol = "0.0", reference = "mboostrs parity-note registry", rationale = "P1.4's last bullet: R models did not carry the same first-contact information as Python. There was no parity_notes() in R at all and summary() said nothing, so a difference between a fit and what its name suggests was reachable from one frontend and not the other. The notes are generated from the Python registry rather than copied, since a second prose registry is the failure this project keeps paying for."),
  list(id = "contract.rust.checked_family_constructors", node_id = "crates/mboostrs-core/src/families.rs::checked_construction", oracle = "MboostrsError::BadFamilyParameter at every invalid boundary", compared_outputs = "error variant; error message", atol = "0.0", rtol = "0.0", reference = "mboostrs-core family parameter domains", rationale = "The published core crate permitted invalid construction: QuantReg::new/with_qoffset, Huber::new, Cindex::new and PropOdds::new accepted impossible values, and Multinomial::new asserted, so a library call could abort the process. try_* constructors return MboostrsError; the unchecked ones are marked as such; mod checked_construction covers every boundary including non-finite values."),
